import numpy as np
from scipy.spatial.distance import cdist
L=open('c4.xyz').read().split('\n')
el=[l.split()[0] for l in L[2:] if len(l.split())==4]
X=np.array([[float(x) for x in l.split()[1:4]] for l in L[2:] if len(l.split())==4])
D=cdist(X,X); np.fill_diagonal(D,9)
for i in range(len(el)):
  for j in range(i+1,len(el)):
    if D[i,j]<1.0 or (el[i]=='H' and el[j]=='H' and D[i,j]<1.7): print(i,el[i],j,el[j],round(D[i,j],2))
# check each C has sensible neighbors count
for i in range(len(el)):
    if el[i]=='C':
        n=sum(1 for j in range(len(el)) if j!=i and j!=88 and D[i,j]<1.65)
        if n not in (3,4): print('C',i,'nbrs',n)
"
